--

CREATE FUNCTION public.swarm_keep_blocked_jobs() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN
        IF OLD.status='active' AND NEW.status<>'active' AND NEW.closed_by='auto'
           AND EXISTS (SELECT 1 FROM blockers b WHERE b.job=OLD.job AND b.state='open'
                       AND (b.protection_rule='always' OR (b.protection_rule='addressed' AND b.waiting_on <> 'external') OR b.until>now())) THEN RETURN NULL; END IF;
        RETURN NEW;
    END $$;


--
-- Name: swarm_keep_goal_jobs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.swarm_keep_goal_jobs() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status <> 'active' AND OLD.status = 'active' AND NEW.goal IS NOT NULL AND length(NEW.goal) > 0
       AND NEW.verdict IS DISTINCT FROM 'met' AND NEW.closed_by = 'auto'
       AND NEW.outcome LIKE 'auto-closed: no live agents%' THEN
        RETURN NULL;
    END IF;
    RETURN NEW;
END $$;


