--
-- Name: agent_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.agent_status AS
 SELECT a.job,
    a.name,
        CASE
            WHEN a.judge THEN 'judge'::text
            WHEN a.verifier THEN 'verifier'::text
            ELSE a.role
        END AS role,
        CASE
            WHEN (a.state = ANY (ARRAY['completed'::text, 'left'::text, 'dead'::text])) THEN a.state
            WHEN ((a.current_tool IS NOT NULL) AND (a.tool_started_at > (now() - make_interval(mins => 60)))) THEN 'running'::text
            WHEN (a.last_seen < (now() - make_interval(mins => 30))) THEN 'dead'::text
            WHEN (a.last_seen < (now() - make_interval(mins => 5))) THEN 'idle'::text
            ELSE a.state
        END AS status,
    a.current_tool,
    a.tool_calls,
    COALESCE(mc.messages, (0)::bigint) AS messages,
    a.joined_at,
    a.last_seen AS last_contact_at,
    a.last_post_at,
    a.left_at AS ended_at,
    a.host,
    a.agent_key,
    a.harness,
    a.model,
    a.os_user,
    a.left_reason,
    a.resume_of
   FROM (public.agents a
     LEFT JOIN LATERAL ( SELECT count(*) AS messages
           FROM public.messages m
          WHERE ((m.job = a.job) AND (m.agent_name = a.name) AND (m.created_at >= a.joined_at))) mc ON (true));


