--
-- Name: job_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.job_status AS
 SELECT j.job,
    j.status,
    j.description,
    j.task,
    j.outcome,
    j.created_by,
    j.session_id,
    j.created_at,
    j.activated_at,
    j.finished_at,
    COALESCE(s.agents, (0)::bigint) AS agents,
    COALESCE(s.started, (0)::bigint) AS started,
    COALESCE(s.running, (0)::bigint) AS running,
    COALESCE(s.idle, (0)::bigint) AS idle,
    COALESCE(s.completed, (0)::bigint) AS completed,
    COALESCE(s.dead_or_left, (0)::bigint) AS dead_or_left,
    COALESCE(m.messages, (0)::bigint) AS messages,
    GREATEST(s.last_contact_at, m.last_post_at) AS last_activity_at,
    j.project,
    j.goal,
    j.verdict,
    j.verdict_reason,
    j.verdict_by,
    j.verdict_at,
    j.completion_forced,
    ( SELECT a.name
           FROM public.agents a
          WHERE ((a.job = j.job) AND a.judge AND (a.left_at IS NULL))) AS judge,
    j.waiting_on,
    j.waiting_since,
    j.closed_by,
    j.supervise,
    j.verdict_next,
    j.max_hours,
    j.waiting_until,
    COALESCE(( SELECT json_agg(row_to_json(b.*) ORDER BY b.id) AS json_agg
           FROM public.blockers b
          WHERE ((b.job = j.job) AND (b.state = 'open'::text))), '[]'::json) AS blockers,
    ( SELECT count(*) AS count
           FROM public.blockers b
          WHERE ((b.job = j.job) AND (b.state = 'open'::text))) AS open_blockers,
    ( SELECT count(*) AS count
           FROM public.blockers b
          WHERE ((b.job = j.job) AND (b.state = 'open'::text) AND ((b.protection_rule = 'always'::text) OR ((b.protection_rule = 'addressed'::text) AND (b.waiting_on <> 'external'::text)) OR (b.until > now())))) AS protected_blockers,
        CASE
            WHEN (j.status <> 'active'::text) THEN j.status
            WHEN (EXISTS ( SELECT 1
               FROM public.blockers b
              WHERE ((b.job = j.job) AND (b.state = 'open'::text)))) THEN 'waiting'::text
            WHEN (COALESCE(j.waiting_on, ''::text) <> ''::text) THEN 'waiting'::text
            WHEN ((COALESCE(s.started, (0)::bigint) + COALESCE(s.running, (0)::bigint)) > 0) THEN 'active'::text
            WHEN ((COALESCE(j.goal, ''::text) <> ''::text) AND (j.verdict IS DISTINCT FROM 'met'::text) AND (COALESCE(s.idle, (0)::bigint) = 0)) THEN 'waiting (goal not met)'::text
            WHEN (COALESCE(GREATEST(s.last_contact_at, m.last_post_at), j.activated_at, j.created_at) > (now() - make_interval(mins => 5))) THEN 'active'::text
            ELSE 'idle'::text
        END AS shown_status
   FROM ((public.jobs j
     LEFT JOIN ( SELECT a.job,
            (sum(a.n))::bigint AS agents,
            (COALESCE(sum(a.n) FILTER (WHERE (a.status = 'started'::text)), (0)::numeric))::bigint AS started,
            (COALESCE(sum(a.n) FILTER (WHERE (a.status = 'running'::text)), (0)::numeric))::bigint AS running,
            (COALESCE(sum(a.n) FILTER (WHERE (a.status = 'idle'::text)), (0)::numeric))::bigint AS idle,
            (COALESCE(sum(a.n) FILTER (WHERE (a.status = 'completed'::text)), (0)::numeric))::bigint AS completed,
            (COALESCE(sum(a.n) FILTER (WHERE (a.status = ANY (ARRAY['dead'::text, 'left'::text]))), (0)::numeric))::bigint AS dead_or_left,
            max(a.last_contact_at) AS last_contact_at
           FROM ( SELECT a_1.job,
                        CASE
                            WHEN (a_1.state = ANY (ARRAY['completed'::text, 'left'::text, 'dead'::text])) THEN a_1.state
                            WHEN ((a_1.current_tool IS NOT NULL) AND (a_1.tool_started_at > (now() - make_interval(mins => 60)))) THEN 'running'::text
                            WHEN (a_1.last_seen < (now() - make_interval(mins => 30))) THEN 'dead'::text
                            WHEN (a_1.last_seen < (now() - make_interval(mins => 5))) THEN 'idle'::text
                            ELSE a_1.state
                        END AS status,
                    count(*) AS n,
                    max(a_1.last_seen) AS last_contact_at
                   FROM public.agents a_1
                  GROUP BY a_1.job,
                        CASE
                            WHEN (a_1.state = ANY (ARRAY['completed'::text, 'left'::text, 'dead'::text])) THEN a_1.state
                            WHEN ((a_1.current_tool IS NOT NULL) AND (a_1.tool_started_at > (now() - make_interval(mins => 60)))) THEN 'running'::text
                            WHEN (a_1.last_seen < (now() - make_interval(mins => 30))) THEN 'dead'::text
                            WHEN (a_1.last_seen < (now() - make_interval(mins => 5))) THEN 'idle'::text
                            ELSE a_1.state
                        END) a
          GROUP BY a.job) s ON ((s.job = j.job)))
     LEFT JOIN ( SELECT messages.job,
            count(*) AS messages,
            max(messages.created_at) FILTER (WHERE (NOT ((messages.agent_name = 'swarm'::text) AND (messages.message ~~ 'Blocker % expired:%'::text)))) AS last_post_at
           FROM public.messages
          GROUP BY messages.job) m ON ((m.job = j.job)));


